using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysNinetyFive()
    {
        var checkout = typeof(ApplicationMarker).Assembly.GetTypes()
            .FirstOrDefault(t => t.Name.Contains("Checkout", StringComparison.Ordinal));

        Assert.True(checkout is not null, "No checkout type exists; cannot calculate a payable total (expected 95.00 for Gold, subtotal 100.00).");
    }
}
